starter.css:
.event { border: 1px solid #c9c4dc; border-radius: 12px; padding: 12px 16px; margin-block-end: 12px; }
.event h3 { margin: 0 0 4px; }
.event p { margin: 4px 0; display: flex; align-items: center; gap: 6px; }
.icon { width: 16px; height: 16px; fill: #5b5670; }
.sold { text-decoration: line-through; color: #6b6680; }

